package kr.tong.sky;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.view.inputmethod.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;

/** Two inputs; no airline request, date-range filter, or writes to saved calendars. */
public class TripSearchActivity extends Activity {
 final ExecutorService worker=Executors.newSingleThreadExecutor();final Handler handler=new Handler(Looper.getMainLooper());
 Spinner region;EditText days;TextView status,empty;ListView list;Button search;final Button[] types=new Button[3];
 final List<String> regions=new ArrayList<>();String origin;boolean oz;volatile boolean closed;volatile int generation;int selectedType;TripSearch.Dataset dataset;TripSearch.Result result;
 @Override public void onCreate(Bundle state){super.onCreate(state);SkyLocale.apply(this);oz=getIntent().getBooleanExtra("oz",false);origin=getIntent().getStringExtra("origin");if(origin==null||!origin.matches("[A-Z]{3}"))origin="ICN";
  LinearLayout root=Ui.root(this);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView title=Ui.text(this,CarrierUi.name(oz)+" 추천일정",21);title.setTypeface(null,Typeface.BOLD);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));top.addView(Ui.button(this,"닫기",v->finish()));root.addView(top);
  root.addView(Ui.text(this,origin+" 출발·귀국 · 저장된 전체 기간",12));LinearLayout form=new LinearLayout(this);form.setGravity(Gravity.BOTTOM);LinearLayout place=new LinearLayout(this);place.setOrientation(LinearLayout.VERTICAL);place.addView(Ui.text(this,"대륙·지역",12));region=new Spinner(this);region.setContentDescription("추천일정 지역");place.addView(region,new LinearLayout.LayoutParams(-1,Ui.dp(this,48)));form.addView(place,new LinearLayout.LayoutParams(0,-2,1));
  LinearLayout length=new LinearLayout(this);length.setOrientation(LinearLayout.VERTICAL);length.addView(Ui.text(this,"여행 일수",12));days=new EditText(this);days.setSingleLine(true);days.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);days.setContentDescription("여행 일수");days.setText(state==null?"7":state.getString("days","7"));days.setSelectAllOnFocus(true);days.setImeOptions(EditorInfo.IME_ACTION_SEARCH);length.addView(days,new LinearLayout.LayoutParams(Ui.dp(this,80),Ui.dp(this,48)));form.addView(length);root.addView(form);
  search=Ui.button(this,"추천일정 찾기",v->search());search.setEnabled(false);root.addView(search);root.addView(Ui.text(this,"출국일 포함 · 귀국편 출발일까지\n같은 지역의 같은 도시 왕복·다른 도시 인아웃을 모두 찾습니다.",12));
  LinearLayout tabs=new LinearLayout(this);for(int i=0;i<3;i++){final int type=i;types[i]=Ui.button(this,TripSearch.LABELS[i]+"\n—",v->{selectedType=type;render();});types[i].setTextSize(12);types[i].setMinWidth(0);types[i].setMinimumWidth(0);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,Ui.dp(this,62),1);lp.rightMargin=i==2?0:Ui.dp(this,5);tabs.addView(types[i],lp);}root.addView(tabs);
  status=Ui.text(this,"저장된 달력을 확인하고 있습니다.",12);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);root.addView(status);FrameLayout body=new FrameLayout(this);list=new ListView(this);list.setDividerHeight(0);body.addView(list,new FrameLayout.LayoutParams(-1,-1));empty=Ui.text(this,"",14);empty.setGravity(Gravity.CENTER);body.addView(empty,new FrameLayout.LayoutParams(-1,-1));list.setEmptyView(empty);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));root.addView(Ui.text(this,"저장 표식 기준 · 비운항·미확인·확인필요 제외\n도시 간 이동편 미포함 · 승급 가능한 항공권 별도 필요",10));setContentView(root);
  selectedType=state==null?0:Math.max(0,Math.min(2,state.getInt("type",0)));String wanted=state==null?"유럽":state.getString("region","유럽");
  worker.execute(()->{try{TripSearch.Dataset loaded=loadDataset();handler.post(()->{if(closed)return;dataset=loaded;for(String name:TripSearch.REGIONS)if(loaded.catalog.optJSONObject("regions").optJSONArray(name)!=null&&loaded.catalog.optJSONObject("regions").optJSONArray(name).length()>0)regions.add(name);region.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,regions));region.setSelection(Math.max(0,regions.indexOf(wanted)));search.setEnabled(true);region.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){search();}});search();});}catch(Exception e){handler.post(()->{if(!closed)status.setText("저장 자료를 불러오지 못했습니다. "+e.getMessage());});}});
  days.setOnEditorActionListener((v,action,event)->{if(action==EditorInfo.IME_ACTION_SEARCH){search();return true;}return false;});
 }
 TripSearch.Dataset loadDataset()throws Exception{return TripSearch.load(getApplicationContext(),origin,oz);}
 void search(){
  if(closed||dataset==null||regions.isEmpty())return;final int count;try{String text=days.getText().toString();if(!text.matches("[0-9]{1,3}"))throw new IllegalArgumentException();count=Integer.parseInt(text);if(count<1||count>360)throw new IllegalArgumentException();}catch(Exception e){days.setError("1~360일을 입력하세요.");result=null;generation++;render();status.setText("여행 일수를 1~360일로 입력하세요.");return;}
  days.setError(null);String selected=regions.get(region.getSelectedItemPosition());final int run=++generation;result=null;render();status.setText(selected+" · "+count+"일 · 저장된 조합을 찾고 있습니다.");
  InputMethodManager keyboard=(InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);keyboard.hideSoftInputFromWindow(days.getWindowToken(),0);
  worker.execute(()->{if(closed||run!=generation)return;try{TripSearch.Result found=TripSearch.find(dataset,selected,count,Search.today(),Search.lastDate(oz));handler.post(()->{if(closed||run!=generation)return;result=found;status.setText(selected+" · "+count+"일 · "+String.format(Locale.KOREA,"%,d",found.total())+"개 조합 · "+(oz?"비즈니스":"프레스티지"));render();});}catch(Exception e){handler.post(()->{if(closed||run!=generation)return;status.setText("추천 일정을 확인하지 못했습니다. "+e.getMessage());});}});
 }
 void render(){for(int i=0;i<3;i++){types[i].setText(TripSearch.LABELS[i]+"\n"+(result==null?"—":String.format(Locale.KOREA,"%,d개",result.groups[i].total)));types[i].setSelected(i==selectedType);types[i].setTextColor(i==selectedType?CarrierUi.accent(oz):Ui.MUTED);types[i].setTypeface(null,i==selectedType?Typeface.BOLD:Typeface.NORMAL);types[i].setContentDescription(TripSearch.LABELS[i]+" "+(result==null?"검색 전":result.groups[i].total+"개")+(i==selectedType?" 선택됨":""));}empty.setText(result==null?"":result.months==0?"이 지역에 저장된 자료가 없습니다.":"조건에 맞는 저장 일정 조합이 없습니다.");list.setAdapter(new Matches(result==null?null:result.groups[selectedType]));}
 final class Matches extends BaseAdapter {
  final TripSearch.Group group;Matches(TripSearch.Group group){this.group=group;}
  public int getCount(){return group==null?0:group.total;}public Object getItem(int pos){return group.get(pos);}public long getItemId(int pos){return pos;}
  public View getView(int pos,View convert,ViewGroup parent){TextView row=convert instanceof TextView?(TextView)convert:Ui.text(TripSearchActivity.this,"",14);TripSearch.Match item=group.get(pos);String cabin=oz?"비즈니스":"프레스티지",out=TripSearch.OUT[group.type].equals("prestigeAward")?"보너스":"승급",back=TripSearch.BACK[group.type].equals("prestigeAward")?"보너스":"승급";row.setText(item.out.date+" → "+item.back.date+"\n"+item.out.name+" IN · "+item.back.name+" OUT\n"+origin+" → "+item.out.code+" / "+item.back.code+" → "+origin+"\n"+cabin+" "+out+" → "+cabin+" "+back+"\n"+(item.out.code.equals(item.back.code)?"같은 도시 왕복":"다른 도시 인아웃")+"\n양방향 중 오래된 수집: "+DataTimes.at(Math.min(item.out.success,item.back.success)));row.setPadding(Ui.dp(TripSearchActivity.this,12),Ui.dp(TripSearchActivity.this,14),Ui.dp(TripSearchActivity.this,12),Ui.dp(TripSearchActivity.this,14));row.setBackgroundColor(pos%2==0?Color.WHITE:Ui.BG);row.setLineSpacing(Ui.dp(TripSearchActivity.this,4),1);return row;}
 }
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("days",days.getText().toString());out.putString("region",region.getSelectedItem()==null?"유럽":region.getSelectedItem().toString());out.putInt("type",selectedType);}
 @Override protected void onDestroy(){closed=true;generation++;handler.removeCallbacksAndMessages(null);worker.shutdownNow();super.onDestroy();}
}
